import { useCallback } from 'react';

import { FilterForm, FilterValue, Option } from 'models/Filters';

interface UseFilterHandlersProps {
  updateForm?: (key: string, value: FilterValue) => void;
  updateQuickFiltersForm?: (key: string, value: FilterValue) => void;
  updateAllForm?: (form: FilterForm) => void;
  apply: () => void;
  applyDirect?: (values: Partial<FilterForm>) => void;
  switchKpi?: (targetKpi: string, applyImmediately?: boolean) => void;
  applyQuickFilters?: () => void;
  resetToDefaults: (defaults: Record<string, FilterValue>) => void;
  resetQuickFiltersToDefaults?: (defaults: Record<string, FilterValue>) => void;
  defaults: FilterForm;
  applied: FilterForm;
  onApply?: () => void;
  onReset?: () => void;
  onClose?: () => void;
}

export const useFilterHandlers = ({
  updateForm,
  updateQuickFiltersForm,
  updateAllForm,
  apply,
  applyDirect,
  switchKpi,
  applyQuickFilters,
  resetToDefaults,
  resetQuickFiltersToDefaults,
  defaults,
  applied,
  onApply,
  onReset,
}: UseFilterHandlersProps) => {
  const handleAutoApplyChange = useCallback(
    (key: string, value: FilterValue) => {
      if (key === 'kpis' && switchKpi) {
        switchKpi(String(value), true);
        onApply?.();
        return;
      }

      if (updateQuickFiltersForm) {
        updateQuickFiltersForm(key, value);
      } else {
        updateForm?.(key, value);
      }

      const applyAction = applyQuickFilters ?? apply;
      setTimeout(() => {
        applyAction();
        onApply?.();
      }, 0);
    },
    [
      switchKpi,
      updateQuickFiltersForm,
      updateForm,
      applyQuickFilters,
      apply,
      onApply,
    ],
  );

  const handleAutoApplyValuesChange = useCallback(
    (changes: FilterForm) => {
      if (applyDirect) {
        applyDirect(changes);
        onApply?.();
        return;
      }

      const updateAction = updateQuickFiltersForm ?? updateForm;
      Object.entries(changes).forEach(([key, value]) => {
        updateAction?.(key, value);
      });

      const applyAction = applyQuickFilters ?? apply;
      setTimeout(() => {
        applyAction();
        onApply?.();
      }, 0);
    },
    [
      applyDirect,
      updateQuickFiltersForm,
      updateForm,
      applyQuickFilters,
      apply,
      onApply,
    ],
  );

  const handleFormChange = useCallback(
    (key: string, value: FilterValue) => {
      if (key === 'kpis' && switchKpi) {
        switchKpi(String(value));
        return;
      }

      updateForm?.(key, value);
    },
    [switchKpi, updateForm],
  );

  const handleFormValuesChange = useCallback(
    (changes: FilterForm) => {
      Object.entries(changes).forEach(([key, value]) => {
        updateForm?.(key, value);
      });
    },
    [updateForm],
  );

  const handleApply = useCallback(() => {
    apply();
    onApply?.();
  }, [apply, onApply]);

  const handleReset = useCallback(() => {
    if (defaults && Object.keys(defaults).length > 0) {
      resetToDefaults(defaults);
    }
  }, [defaults, resetToDefaults]);

  const handleResetAndApply = useCallback(() => {
    const resetAction = resetQuickFiltersToDefaults ?? resetToDefaults;
    const applyAction = applyQuickFilters ?? apply;

    if (defaults && Object.keys(defaults).length > 0) {
      resetAction(defaults);
    }

    applyAction();

    setTimeout(() => {
      onReset?.();
    }, 0);
  }, [
    defaults,
    resetQuickFiltersToDefaults,
    resetToDefaults,
    applyQuickFilters,
    apply,
    onReset,
  ]);

  const handleAutoApplyValueChange = useCallback(
    (fieldKey: string, option: Option) => {
      handleAutoApplyChange(fieldKey, option?.value);
    },
    [handleAutoApplyChange],
  );

  const handleCancelModalFilter = useCallback(() => {
    updateAllForm?.(applied);
  }, [applied, updateAllForm]);

  const handleFormValueChange = useCallback(
    (fieldKey: string, option: Option) => {
      handleFormChange(fieldKey, option?.value);
    },
    [handleFormChange],
  );

  return {
    handleAutoApplyChange,
    handleAutoApplyValuesChange,
    handleFormChange,
    handleFormValuesChange,
    handleApply,
    handleReset,
    handleResetAndApply,
    handleAutoApplyValueChange,
    handleCancelModalFilter,
    handleFormValueChange,
  };
};
